#include <stdlib.h>
static void f(struct TreeNode*n,int t,int*b,int len,int***o,int**cols,int*c,int*cap){if(!n)return;b[len++]=n->val;t-=n->val;if(!n->left&&!n->right&&t==0){if(*c==*cap){*cap*=2;*o=realloc(*o,*cap*sizeof(int*));*cols=realloc(*cols,*cap*sizeof(int));}(*o)[*c]=malloc(len*sizeof(int));for(int i=0;i<len;i++)(*o)[*c][i]=b[i];(*cols)[(*c)++]=len;return;}f(n->left,t,b,len,o,cols,c,cap);f(n->right,t,b,len,o,cols,c,cap);}int** pathSum(struct TreeNode*r,int t,int*rs,int**rc){int cap=16,c=0,**o=malloc(cap*sizeof(int*)),*cols=malloc(cap*sizeof(int)),*b=malloc(5000*sizeof(int));f(r,t,b,0,&o,&cols,&c,&cap);free(b);*rs=c;*rc=cols;return o;}
